def parse_fasta(path):
    seqs = {}; name = None
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line: continue
            if line.startswith('>'): name = line[1:].strip(); seqs[name] = ''
            else: seqs[name] += line.lower()
    return seqs
